1	import {Ajv} from 'ajv';
2	import type {ValidateFunction} from 'ajv';
3	import type {ToolDefinition} from '../../types/ai.js';
4	import type {OutgoingMessage} from '../../types/messages.js';
5	import {log} from '../../shared/logger.js';
6	
7	export interface ToolResponse {
8	  result: string;
9	  clientMessages?: OutgoingMessage[];
10	  suppressAssistantResponse?: boolean;
11	}
12	
13	export interface ToolContext {
14	  userId: string | number;
15	  sessionId?: string;
16	  workspaceId?: string | number;
17	  authHeaders?: {
18	    cookie?: string;
19	    authorization?: string;
20	    host?: string;
21	  };
22	}
23	
24	export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;
25	
26	export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
27	  return typeof response === 'string' ? {result: response} : response;
28	}
29	
30	export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);
31	
32	export interface RegisteredTool {
33	  definition: ToolDefinition;
34	  execute: ToolExecutor;
35	}
36	
37	interface StoredTool {
38	  definitionSource: ToolDefinitionSource;
39	  execute: ToolExecutor;
40	}
41	
42	export class ToolRegistry {
43	  private readonly tools = new Map<string, StoredTool>();
44	  private readonly ajv = new Ajv({allErrors: true});
45	  private readonly staticValidators = new Map<string, ValidateFunction>();
46	  private readonly dynamicValidatorCache = new WeakMap<object, ValidateFunction>();
47	
48	  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
49	    return typeof source === 'function' ? source() : source;
50	  }
51	
52	  private compileSchema(schema: Record<string, unknown>, toolName: string): ValidateFunction {
53	    try {
54	      return this.ajv.compile(schema);
55	    } catch (err) {
56	      throw new Error(`Tool '${toolName}' has an uncompilable inputSchema: ${(err as Error).message}`, {cause: err});
57	    }
58	  }
59	
60	  private getValidator(name: string, tool: StoredTool): ValidateFunction {
61	    if (typeof tool.definitionSource !== 'function') {
62	      return this.staticValidators.get(name)!;
63	    }
64	    const definition = tool.definitionSource();
65	    const schema = definition.inputSchema;
66	    const cached = this.dynamicValidatorCache.get(schema);
67	    if (cached) return cached;
68	    const compiled = this.compileSchema(schema, name);
69	    this.dynamicValidatorCache.set(schema, compiled);
70	    return compiled;
71	  }
72	
73	  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
74	    const resolved = this.resolveDefinition(definition);
75	    if (typeof definition !== 'function') {
76	      this.staticValidators.set(resolved.name, this.compileSchema(resolved.inputSchema, resolved.name));
77	    }
78	    this.tools.set(resolved.name, {definitionSource: definition, execute});
79	  }
80	
81	  get(name: string): RegisteredTool | undefined {
82	    const tool = this.tools.get(name);
83	    if (!tool) return undefined;
84	    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
85	  }
86	
87	  getDefinitions(): ToolDefinition[] {
88	    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
89	  }
90	
91	  getPromptInstructions(): string[] {
92	    return this.getDefinitions()
93	      .filter(t => t.promptInstructions)
94	      .map(t => `${t.name}: ${t.promptInstructions}`);
95	  }
96	
97	  getExamplePrompts(): string[] {
98	    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
99	  }
100	
101	  has(name: string): boolean {
102	    return this.tools.has(name);
103	  }
104	
105	  /** Validates input against the tool's inputSchema before execution; see specs/hal-engine-tool-input-validation/spec.md. */
106	  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
107	    const tool = this.tools.get(name);
108	    if (!tool) {
109	      log.warn('tool', 'tool not found', {name});
110	      throw new Error(`Unknown tool: ${name}`);
111	    }
112	
113	    const validate = this.getValidator(name, tool);
114	
115	    const valid = validate(input);
116	    if (!valid) {
117	      const errors = validate.errors ?? [];
118	      const message = errors.map(e => `${e.instancePath || '(root)'} ${e.message}`).join('; ');
119	      log.warn('tool', 'input validation failed', {name, paths: errors.map(e => e.instancePath)});
120	      return {result: `Tool '${name}' input invalid: ${message}`};
121	    }
122	
123	    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
124	    const rawResult = await tool.execute(input, context);
125	    const response = normalizeToolResponse(rawResult);
126	    log.info('tool', 'execution complete', {
127	      name,
128	      rawType: typeof rawResult,
129	      clientMessageCount: response.clientMessages?.length ?? 0,
130	      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
131	      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
132	    });
133	    return response;
134	  }
135	}
136

