 const REGISTRY = {} as ToolRegistry;

+describe('addUsage', () => {
+  it('sums all fields when both operands are defined', () => {
+    expect(
+      addUsage(
+        {inputTokens: 10, outputTokens: 5, totalTokens: 15},
+        {inputTokens: 20, outputTokens: 10, totalTokens: 30}
+      )
+    ).toEqual({inputTokens: 30, outputTokens: 15, totalTokens: 45});
+  });
+
+  it('returns the defined operand when the accumulator is undefined', () => {
+    expect(addUsage(undefined, {inputTokens: 10, outputTokens: 5, totalTokens: 15})).toEqual({
+      inputTokens: 10,
+      outputTokens: 5,
+      totalTokens: 15,
+    });
+  });
+
+  it('returns the accumulator when the new round reports no usage', () => {
+    expect(addUsage({inputTokens: 10, outputTokens: 5, totalTokens: 15}, undefined)).toEqual({
+      inputTokens: 10,
+      outputTokens: 5,
+      totalTokens: 15,
+    });
+  });
+
+  it('returns undefined when both operands are undefined', () => {
+    expect(addUsage(undefined, undefined)).toBeUndefined();
+  });
+});
+
 describe('shouldContinueToolLoop', () => {
